arguments.command:
mkdir -p /workspace/submission/infra && cd /workspace/submission/infra
cat > versions.tf <<'EOF'
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "6.51.0"
    }
  }
}

provider "aws" {
  region     = var.region
  access_key = "test"
  secret_key = "test"

  skip_credentials_validation = true
  skip_metadata_api_check     = true
  skip_requesting_account_id  = false
  s3_use_path_style           = true

  endpoints {
    cloudwatchlogs   = var.aws_endpoint_url
    cognitoidp       = var.aws_endpoint_url
    dynamodb         = var.aws_endpoint_url
    ec2              = var.aws_endpoint_url
    ecs              = var.aws_endpoint_url
    elasticache      = var.aws_endpoint_url
    elbv2            = var.aws_endpoint_url
    iam              = var.aws_endpoint_url
    kms              = var.aws_endpoint_url
    lambda           = var.aws_endpoint_url
    rds              = var.aws_endpoint_url
    s3               = var.aws_endpoint_url
    scheduler        = var.aws_endpoint_url
    sqs              = var.aws_endpoint_url
    sts              = var.aws_endpoint_url
  }
}
EOF
cat > variables.tf <<'EOF'
# All values come from /workspace/config/config.json (passed with -var-file by deploy.sh/destroy.sh).

variable "resource_prefix" {
  type = string
}

variable "region" {
  type    = string
  default = "us-east-1"
}

variable "aws_endpoint_url" {
  type    = string
  default = "http://aws:4566"
}

variable "db_name" {
  type = string
}

variable "db_username" {
  type = string
}

variable "db_password" {
  type      = string
  sensitive = true
}

variable "api_image" {
  type = string
}

variable "projector_image" {
  type = string
}

variable "relay_image" {
  type = string
}

variable "archiver_image" {
  type = string
}

# Digests are accepted for traceability (declared so the shared var-file is consumed without warnings).
variable "api_image_id" {
  type    = string
  default = ""
}

variable "projector_image_id" {
  type    = string
  default = ""
}

variable "relay_image_id" {
  type    = string
  default = ""
}

variable "archiver_image_id" {
  type    = string
  default = ""
}

locals {
  prefix = var.resource_prefix
  azs    = ["${var.region}a", "${var.region}b"]

  tags = {
    ClearLedgerDeployment = var.resource_prefix
  }

  vpc_cidr = "10.42.0.0/16"
  public_cidrs  = ["10.42.0.0/24", "10.42.1.0/24"]
  private_cidrs = ["10.42.10.0/24", "10.42.11.0/24"]

  # Runtime wiring shared by the workloads.
  database_url = "postgres://${var.db_username}:${var.db_password}@${aws_db_instance.main.address}:${aws_db_instance.main.port}/${var.db_name}"
  valkey_url   = "redis://${aws_elasticache_replication_group.main.primary_endpoint_address}:6379"
  audit_prefix = "ledger-audit/"
}
EOF
cat > kms.tf <<'EOF'
locals {
  kms_purposes = toset(["database", "messaging", "projection", "audit"])
}

resource "aws_kms_key" "this" {
  for_each = local.kms_purposes

  description             = "ClearLedger ${each.key} key for ${local.prefix}"
  enable_key_rotation     = true
  deletion_window_in_days = 10

  tags = merge(local.tags, { Name = "${local.prefix}-${each.key}" })
}

resource "aws_kms_alias" "this" {
  for_each = local.kms_purposes

  name          = "alias/${local.prefix}-${each.key}"
  target_key_id = aws_kms_key.this[each.key].key_id
}
EOF
cat > logs.tf <<'EOF'
locals {
  log_groups = {
    api       = "/clearledger/${local.prefix}/api"
    projector = "/clearledger/${local.prefix}/projector"
    relay     = "/clearledger/${local.prefix}/outbox-relay"
    archiver  = "/clearledger/${local.prefix}/audit-archiver"
  }
}

resource "aws_cloudwatch_log_group" "this" {
  for_each = local.log_groups

  name              = each.value
  retention_in_days = 14

  tags = merge(local.tags, { Name = "${local.prefix}-${each.key}-logs" })
}
EOF

cd /workspace/submission/infra
cat > network.tf <<'EOF'
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, { Name = "${local.prefix}-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, { Name = "${local.prefix}-igw" })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.tags, { Name = "${local.prefix}-public-${count.index}", Tier = "public" })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.tags, { Name = "${local.prefix}-private-${count.index}", Tier = "private" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.tags, { Name = "${local.prefix}-public-rt" })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, { Name = "${local.prefix}-private-rt" })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# Security groups. Rules are declared inline so Terraform is authoritative over
# them and removes any out-of-band rule on the next apply.
# ---------------------------------------------------------------------------

resource "aws_security_group" "alb" {
  name        = "${local.prefix}-alb"
  description = "ClearLedger ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "API port inside the VPC only"
    from_port   = 8080
    to_port     = 8080
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.tags, { Name = "${local.prefix}-alb" })
}

resource "aws_security_group" "ecs" {
  name        = "${local.prefix}-ecs"
  description = "ClearLedger API tasks"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "API port from the ALB only"
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "AWS control plane and data stores"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.tags, { Name = "${local.prefix}-ecs" })
}

resource "aws_security_group" "rds" {
  name        = "${local.prefix}-rds"
  description = "ClearLedger PostgreSQL"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "PostgreSQL from API tasks"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  egress {
    description = "VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.tags, { Name = "${local.prefix}-rds" })
}

resource "aws_security_group" "valkey" {
  name        = "${local.prefix}-valkey"
  description = "ClearLedger Valkey"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Valkey from API tasks"
    from_port       = 6379
    to_port         = 6379
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  egress {
    description = "VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.tags, { Name = "${local.prefix}-valkey" })
}
EOF

cd /workspace/submission/infra
cat > iam.tf <<'EOF'
# Six dedicated workload roles. Each role gets exactly one canonical inline policy that contains
# scoped Allow statements plus explicit Deny guardrails. deploy.sh removes anything else attached
# out-of-band.

locals {
  roles = {
    ecs_execution = "ecs-tasks.amazonaws.com"
    ecs_task      = "ecs-tasks.amazonaws.com"
    projector     = "lambda.amazonaws.com"
    relay         = "lambda.amazonaws.com"
    archiver      = "lambda.amazonaws.com"
    scheduler     = "scheduler.amazonaws.com"
  }

  q_arn    = aws_sqs_queue.main.arn
  dlq_arn  = aws_sqs_queue.dlq.arn
  t_arn    = aws_dynamodb_table.projection.arn
  idx_arn  = "${aws_dynamodb_table.projection.arn}/index/AccountIndex"
  b_arn    = aws_s3_bucket.audit.arn
  b_objs   = "${aws_s3_bucket.audit.arn}/*"
  b_prefix = "${aws_s3_bucket.audit.arn}/${local.audit_prefix}*"

  key_arn = { for k, v in aws_kms_key.this : k => v.arn }

  # Log group ARN plus its stream ARN form (arn:...:log-group:<name>:*).
  log_arns = {
    for k, v in aws_cloudwatch_log_group.this : k => [v.arn, "${v.arn}:*"]
  }

  logs_write_actions = ["logs:CreateLogStream", "logs:PutLogEvents", "logs:DescribeLogStreams"]
  logs_deny_actions  = ["logs:CreateLogStream", "logs:PutLogEvents"]
  kms_use_actions    = ["kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"]
  kms_deny_actions   = ["kms:Decrypt", "kms:GenerateDataKey"]

  ddb_rw_actions  = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:Query"]
  s3_deny_actions = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket"]

  keys_except = {
    for role, allowed in {
      ecs_execution = []
      ecs_task      = ["messaging", "projection"]
      projector     = ["messaging", "projection"]
      relay         = ["messaging", "database"]
      archiver      = ["audit", "database"]
      scheduler     = []
    } : role => [for k in sort(tolist(local.kms_purposes)) : local.key_arn[k] if !contains(allowed, k)]
  }

  keys_allowed = {
    ecs_task  = [local.key_arn["messaging"], local.key_arn["projection"]]
    projector = [local.key_arn["messaging"], local.key_arn["projection"]]
    relay     = [local.key_arn["messaging"], local.key_arn["database"]]
    archiver  = [local.key_arn["audit"], local.key_arn["database"]]
  }

  other_logs = {
    for role, own in {
      ecs_execution = ["api"]
      ecs_task      = ["api"]
      projector     = ["projector"]
      relay         = ["relay"]
      archiver      = ["archiver"]
      scheduler     = []
    } : role => flatten([for k in ["api", "projector", "relay", "archiver"] : local.log_arns[k] if !contains(own, k)])
  }

  policy_statements = {
    ecs_execution = [
      {
        Sid      = "WriteOwnApiLogs"
        Effect   = "Allow"
        Action   = local.logs_write_actions
        Resource = local.log_arns["api"]
      },
      {
        Sid      = "DenyQueueAccess"
        Effect   = "Deny"
        Action   = ["sqs:SendMessage", "sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource = [local.q_arn, local.dlq_arn]
      },
      {
        Sid      = "DenyProjectionAccess"
        Effect   = "Deny"
        Action   = local.ddb_rw_actions
        Resource = [local.t_arn, local.idx_arn]
      },
      {
        Sid      = "DenyAuditBucketAccess"
        Effect   = "Deny"
        Action   = local.s3_deny_actions
        Resource = [local.b_arn, local.b_objs]
      },
      {
        Sid      = "DenyAllKeyUsage"
        Effect   = "Deny"
        Action   = local.kms_deny_actions
        Resource = local.keys_except["ecs_execution"]
      },
      {
        Sid      = "DenyForeignLogGroups"
        Effect   = "Deny"
        Action   = local.logs_deny_actions
        Resource = local.other_logs["ecs_execution"]
      },
    ]

    ecs_task = [
      {
        Sid      = "PublishToMainQueue"
        Effect   = "Allow"
        Action   = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"]
        Resource = [local.q_arn]
      },
      {
        Sid      = "ReadProjection"
        Effect   = "Allow"
        Action   = ["dynamodb:GetItem", "dynamodb:Query", "dynamodb:DescribeTable"]
        Resource = [local.t_arn, local.idx_arn]
      },
      {
        Sid      = "UseMessagingAndProjectionKeys"
        Effect   = "Allow"
        Action   = local.kms_use_actions
        Resource = local.keys_allowed["ecs_task"]
      },
      {
        Sid      = "WriteOwnApiLogs"
        Effect   = "Allow"
        Action   = local.logs_write_actions
        Resource = local.log_arns["api"]
      },
      {
        Sid      = "DenyQueueConsumption"
        Effect   = "Deny"
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource = [local.q_arn]
      },
      {
        Sid      = "DenyDeadLetterQueueAccess"
        Effect   = "Deny"
        Action   = ["sqs:SendMessage", "sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource = [local.dlq_arn]
      },
      {
        Sid      = "DenyProjectionMutation"
        Effect   = "Deny"
        Action   = ["dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:DeleteTable"]
        Resource = [local.t_arn]
      },
      {
        Sid      = "DenyAuditBucketAccess"
        Effect   = "Deny"
        Action   = local.s3_deny_actions
        Resource = [local.b_arn, local.b_objs]
      },
      {
        Sid      = "DenyForeignKeyUsage"
        Effect   = "Deny"
        Action   = local.kms_deny_actions
        Resource = local.keys_except["ecs_task"]
      },
      {
        Sid      = "DenyForeignLogGroups"
        Effect   = "Deny"
        Action   = local.logs_deny_actions
        Resource = local.other_logs["ecs_task"]
      },
    ]

    projector = [
      {
        Sid      = "ConsumeMainQueue"
        Effect   = "Allow"
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage", "sqs:GetQueueAttributes", "sqs:ChangeMessageVisibility"]
        Resource = [local.q_arn]
      },
      {
        Sid      = "ForwardToDeadLetterQueue"
        Effect   = "Allow"
        Action   = ["sqs:SendMessage"]
        Resource = [local.dlq_arn]
      },
      {
        Sid      = "UpsertProjection"
        Effect   = "Allow"
        Action   = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:Query"]
        Resource = [local.t_arn, local.idx_arn]
      },
      {
        Sid      = "UseMessagingAndProjectionKeys"
        Effect   = "Allow"
        Action   = local.kms_use_actions
        Resource = local.keys_allowed["projector"]
      },
      {
        Sid      = "WriteOwnProjectorLogs"
        Effect   = "Allow"
        Action   = local.logs_write_actions
        Resource = local.log_arns["projector"]
      },
      {
        Sid      = "DenyMainQueuePublish"
        Effect   = "Deny"
        Action   = ["sqs:SendMessage"]
        Resource = [local.q_arn]
      },
      {
        Sid      = "DenyDeadLetterQueueConsumption"
        Effect   = "Deny"
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource = [local.dlq_arn]
      },
      {
        Sid      = "DenyProjectionDeletion"
        Effect   = "Deny"
        Action   = ["dynamodb:DeleteItem", "dynamodb:DeleteTable"]
        Resource = [local.t_arn]
      },
      {
        Sid      = "DenyAuditBucketAccess"
        Effect   = "Deny"
        Action   = local.s3_deny_actions
        Resource = [local.b_arn, local.b_objs]
      },
      {
        Sid      = "DenyForeignKeyUsage"
        Effect   = "Deny"
        Action   = local.kms_deny_actions
        Resource = local.keys_except["projector"]
      },
      {
